      source: 'Mankiw《Principles of Economics》；Krugman & Wells',
      brief: `**需求法則**：其他條件不變下，價格越高、需求量越低（需求曲線負斜率）。
**供給法則**：價格越高、供給量越高（供給曲線正斜率）。

**最常考也最常錯的一組區分**：

| | 需求量變動 | 需求變動 |
|---|---|---|
| 觸發原因 | **該商品自身的價格**改變 | 價格以外的因素改變 |
| 圖形表現 | **沿著同一條曲線移動** | **整條曲線平移** |
| 英文 | change in quantity demanded | change in demand |

**影響需求（曲線平移）的五個因素**：所得、相關財貨價格（替代品／互補品）、偏好、預期、購買人數。
**影響供給的因素**：投入成本、技術、相關財貨價格、預期、賣方人數。

**均衡**：供給量等於需求量之處，\`Qd = Qs\`，決定均衡價格與均衡數量。

**價格機能（看不見的手）做兩件事**：
1. **傳遞資訊**——價格上漲代表相對稀缺
2. **提供誘因**——高價使買方節約、賣方增產

**超額需求（短缺）→ 價格上漲；超額供給（過剩）→ 價格下跌**，市場自動回到均衡。`,
      advanced: `**「其他條件不變」（ceteris paribus）是全部推論的前提**。現實中同時有多個因素在動，因此觀察到「價格上漲、成交量也上漲」並不違反需求法則——那是**供給與需求同時移動**的結果（多半是需求增加得比供給多）。**面試若被問「房價一直漲、成交量也增加，是不是推翻了需求法則」，這就是標準答法。**

**比較靜態分析**：一方移動時結果明確，兩方同時移動時，**價格與數量必有一個方向不確定**：

| 變動 | 均衡價格 | 均衡數量 |
|---|---|---|
| 需求增加 | 上升 | 增加 |
| 供給增加 | 下降 | 增加 |
| 需求增、供給增 | **不確定** | 增加 |
| 需求增、供給減 | 上升 | **不確定** |

**替代品與互補品的判準是交叉彈性的正負**（見 [[eco-02-02]]）：替代品為正（咖啡漲、茶的需求增加），互補品為負（汽車漲、汽油需求減少）。

**正常財與劣等財**：所得上升時需求增加者為正常財，減少者為劣等財。**劣等財不等於品質差**，它描述的是「所得變高後就不太買了」的關係，例如所得提高後改買新品而減少購買二手貨。

**價格機能失靈的邊界**：價格能有效配置資源，前提是**財產權明確、資訊充分、無外部性、有競爭**。四者任一不成立就會出現市場失靈（見 [[eco-07-01]]）。**行銷的價值主張其實建立在同一組前提上**——當資訊不對稱時，品牌才會成為品質訊號（連回 [[mkt-06-02]]）。

**存量與流量**：需求與供給談的是**每期的流量**（每月幾杯咖啡），不是存量。學生最常在寫房市或勞動市場時混淆這兩者。`,
      example: `**雞蛋價格上漲**是拆解供需最方便的案例。若上漲來自禽流感導致產量下降，屬**供給減少**（曲線左移），結果是價格上升、成交量下降；若上漲來自防疫期間家庭自炊增加，屬**需求增加**（曲線右移），結果是價格上升、成交量上升。**兩者的價格方向相同、數量方向相反**，因此觀察數量的變化，就能反推是哪一邊在動——這是把理論用在現實資料上的基本功。

**替代與互補的實例**也隨處可見：手搖飲漲價時，超商咖啡的需求會增加（替代品）；印表機降價時，碳粉匣的需求會增加（互補品）。後者正是行銷上互補品訂價的經濟學基礎（連回 [[mkt-07-03]]）。`,
