          explain: '價格上限若設在均衡價格之上，市場價格本來就低於該上限，管制不具拘束力；唯有訂在均衡之下才會發生作用，此時需求量大於供給量而形成短缺。短缺會使配給改以排隊、關係或品質下降等非價格方式進行，並產生無謂損失，因此交易量確實會受影響。'
