          explain: '彈性以百分比變動計算，因此除了斜率外還取決於所在點的價格與數量水準。在直線需求曲線上，高價低量處價格變動的百分比相對較小、數量變動的百分比相對較大，故為富彈性；低價高量處則相反。中點恰為單位彈性，此時總收益達到極大。'
