            '定義交叉彈性並說明替代品與互補品的判準',
            '論述交叉彈性作為競爭者辨識工具的價值，並連結 SSNIP 檢定',
            '定義供給彈性並說明其決定因素',
            '說明 Marshall 的三個時間層次與供給衝擊的價格效果',
