          def: '租稅實際由買賣雙方分別負擔的比例。取決於供需雙方的相對價格彈性，彈性較小的一方負擔較多，與法律上規定由誰繳納無關。',
          tip: '記住公式的直覺：消費者負擔比例等於供給彈性除以兩彈性之和，需求越無彈性、消費者扛得越多。菸稅是最好用的例子。'
