          def: '能為消費者帶來相同效用水準的各種商品組合所連成的曲線。其性質包含負斜率、凸向原點、彼此不相交，且越往右上方效用越高。',
          tip: '四個性質要能背出來，並說明「不能相交」的理由是相交會導致偏好矛盾，這是最常被追問的一點。'
