          def: '在其他生產要素固定的短期下，持續增加某一變動要素的使用量，該要素的邊際產量終將遞減。其成因為固定要素被越來越多的變動要素所分攤。',
          tip: '務必強調前提是「其他要素固定」，這是它與規模報酬遞減最根本的差別，也是最常被混淆的地方。'
