      title: '完全競爭市場',
      tags: ['必考', '核心'],
      source: 'Mankiw《Principles of Economics》；Pindyck & Rubinfeld',
      brief: `**完全競爭的四個假設**：
1. 買賣雙方**人數眾多**，各自規模都很小
2. 產品**完全同質**
3. **自由進出**產業
4. **資訊充分**

結果是：**每家廠商都是價格接受者**（price taker），面對一條**水平的需求曲線**——想賣多少就賣多少，但只能照市價。

**因此 \`P = AR = MR\`**（價格＝平均收益＝邊際收益），這是完全競爭最重要的技術特徵。

**利潤極大化的產量條件（所有市場結構通用）**：
> \`MR = MC\`
在完全競爭下即為 **\`P = MC\`**

**短期的三種狀況**（用 P 與成本曲線比較）：

| 條件 | 結果 |
|---|---|
| \`P > ATC\` | 有超額利潤 |
| \`P = ATC\` | 損益兩平（正常利潤） |
| \`AVC < P < ATC\` | 虧損但**應繼續生產**（能分攤部分固定成本） |
| \`P < AVC\` | **應停業** |

**長期均衡三個條件同時成立**：
> \`P = MR = MC = 最低 ATC\`，**經濟利潤為零**

因為自由進出：有超額利潤 → 新廠商進入 → 價格下跌；虧損 → 廠商退出 → 價格回升。`,
      advanced: `**「經濟利潤為零」不等於沒賺錢**——這是最常被誤解的結論。經濟成本已包含隱含成本，因此零經濟利潤代表廠商仍取得**正常利潤**（[[eco-04-02]]），即與次佳用途相同的報酬。**面試若被問「利潤為零為何還營業」，這就是標準答案。**

**完全競爭的效率性質**（福利經濟學第一定理的具體展現，連回 [[eco-01-02]]）：
- **配置效率**（allocative efficiency）：\`P = MC\`，代表消費者對最後一單位的評價等於社會生產它的成本 → **總剩餘最大**
- **生產效率**（productive efficiency）：長期在**最低 ATC** 生產 → 以最低成本生產

**這兩項效率是評價其他市場結構的基準**——獨占之所以被認為有效率損失，正是因為 \`P > MC\`（見 [[eco-05-02]]）。

**短期供給曲線的推導**：廠商依 \`P = MC\` 決定產量，因此**個別廠商的短期供給曲線就是 AVC 最低點以上的 MC 曲線**；市場供給曲線為所有廠商供給的水平加總。**能講出這一句，代表你理解供給曲線的來源，而不只是把它當作給定的線。**

**長期供給曲線的三種形狀**：
- **成本不變產業**：長期供給水平（要素價格不受產業規模影響）
- **成本遞增產業**：長期供給正斜率（產業擴張推升要素價格，如特定土地或專業人力）
- **成本遞減產業**：長期供給負斜率（產業擴張帶來外部規模經濟，較罕見）

**完全競爭的現實意義**：嚴格符合四項假設的市場幾乎不存在。但它的價值不在描述現實，而在於**作為效率基準**——與 [[eco-03-03]] 提到的「理性模型作為基準」是同一種方法論。**當我們說某市場「缺乏競爭」，隱含的比較對象就是這個模型。**

**最接近的現實例子**是農產品批發、外匯市場與部分大宗商品：產品高度同質、參與者眾多、資訊透明。**而個別業者「沒有訂價權」正是完全競爭最具體的體驗**——這也連回 [[mkt-02-02]] 五力全開的產業處境。`,
      example: `**農產品批發市場**是最接近完全競爭的場域：同一等級的產品幾乎無差異、賣方眾多、價格公開透明，個別農民無法自訂價格，只能接受拍賣結果。這正是「價格接受者」的具體樣態，也解釋了為何農業必須靠差異化與品牌化才能脫離價格接受者的處境（連回 [[eco-02-03]] 的農產品悖論）。

**短期停業點的實務判斷**：若一家工廠的售價已低於平均變動成本，代表每多生產一單位都在擴大虧損，此時停產優於繼續營運；但若售價仍高於平均變動成本，即使低於平均總成本，繼續生產仍能貢獻部分固定成本的回收，優於立即停產。**這個判準在景氣低迷時特別重要——它區分了「該撐」與「該停」。**

**自由進出的力量**在餐飲業相當明顯：某一類餐飲爆紅、利潤豐厚時，短期內大量新店湧入，供給增加使價格與利潤回落；反之經營困難時大量退出，存活者的處境才改善。這正是長期經濟利潤趨近於零的調整機制。`,
