          def: '分析序列賽局的標準方法，由賽局樹的最末端往前推導：先確定最後決策者的最適選擇，再據此決定前一階段的最適行動，逐步回推至起點。',
          tip: '一句話說明方法的精神：先想清楚最後一步別人會怎麼選，才知道自己現在該怎麼走。'
