      source: 'Pigou；Coase（1960）《The Problem of Social Cost》；Mankiw',
      brief: `**外部性**：某人的行為對第三者造成影響，卻**未透過價格反映**。

| 類型 | 例子 | 市場結果 |
|---|---|---|
| **負外部性** | 污染、噪音、塞車 | **產量過多**（私人成本 < 社會成本） |
| **正外部性** | 教育、疫苗、研發 | **產量過少**（私人利益 < 社會利益） |

**核心機制**：決策者只考慮**自己**承擔的成本與獲得的利益，因此**私人最適 ≠ 社會最適**，兩者的落差就是無謂損失。

**矯正手段**：
1. **Pigou 稅／補貼**：對負外部性課稅（稅額＝外部成本），對正外部性補貼 → **把外部成本「內部化」**
2. **可交易許可**（如碳權）：先設總量，再讓市場分配
3. **管制**（直接規定上限或禁止）
4. **Coase 定理**：財產權明確且**交易成本為零**時，當事人自行協商即可達成效率結果，**且與財產權歸屬無關**

**Coase 定理的真正意義常被誤讀**：它不是說「政府不必介入」，而是說——**當交易成本高時，市場無法自行解決，此時財產權的初始配置與制度設計就變得關鍵**。`,
      advanced: `**Pigou 稅 vs 可交易許可的取捨**（申論常考）：
- **Pigou 稅**：**價格確定、數量不確定**。政府訂稅率，減量多少由市場決定。
- **可交易許可**：**數量確定、價格不確定**。政府訂總量，價格由交易決定。

**選擇取決於哪一種不確定性代價較高**：若外部成本在超過某門檻後急劇上升（如生態不可逆的臨界點），**總量管制較安全**；若減量成本不確定而過高的成本會傷害經濟，**課稅較可控**。**能講出這個取捨，代表你理解兩者不只是形式差異。**

**可交易許可的效率優勢**：它讓**減量成本最低的廠商多減量**——減量便宜的廠商賣出許可、減量昂貴的廠商買入。因此**達成同樣總減量的社會成本最低**。這是市場機制在環境政策上最有力的應用。

**Coase 定理的三個條件**：財產權明確、交易成本低、資訊充分。現實中三者常不成立：
- **當事人眾多時交易成本極高**（全球暖化的當事人是全人類，不可能協商）
- **資訊不對稱**使協商難以達成
- **策略性行為**（漫天喊價）也會阻礙協議

**因此 Coase 的貢獻不在於主張放任，而在於指出「外部性問題的本質是交易成本與財產權」**——這開創了法律經濟學。**面試答這題時，能點出這一層會明顯高於「Coase 說私人協商就好」的常見誤解。**

**行為面的補充**：**推力（nudge）** 提供了第四種工具——改變**預設選項**與呈現方式，如器官捐贈的預設同意制、電費帳單顯示鄰居用量。它成本極低且不限制選擇自由（自由家長制），但**效果規模通常小於價格工具**，適合作為補充而非替代。

**與 ESG 的連結**：企業的永續行動（[[mkt-10-04]]）在經濟學上就是**外部性的自願內部化**。它之所以可能是理性的，是因為預期未來的管制、消費者偏好或資本市場評價會把外部成本轉為私人成本——**這也解釋了為何 ESG 在管制預期較強的產業推進得較快**。`,
      example: `**碳定價的兩種形式**清楚展現了政策工具的取捨：碳稅先定價格、減量多少由市場決定；碳權交易先定總量、價格由市場決定。若目標是確保排放量不超過特定門檻，總量管制較能保證結果；若擔心減量成本失控傷害產業，課稅較可控。**兩者不是誰比較好，而是要控制哪一種不確定性。**

**塞車與擁擠定價**是負外部性的日常案例：每位駕駛只考慮自己的時間與油錢，未計入自己對其他用路人造成的延誤，因此車流量高於社會最適。擁擠時段收費正是把這項外部成本內部化。

**教育與疫苗的正外部性**則說明了補貼的理由：受教育者與接種者自身固然受益，但社會也因整體人力素質提升與疾病傳播降低而受益。若完全依私人意願決定，數量將低於社會最適，這是公共補貼的經濟學依據。**Coase 式的私人協商在此完全不可行**——受益的第三者是整個社會，交易成本高到無法協商。`,
